+impl WorkspaceSpec {
+    pub fn alias(&self) -> Option<&str> {
+        if self.relative_path().is_some() {
+            return None;
+        }
+        self.suffix
+            .rsplit_once('@')
+            .and_then(|(name, _)| (!name.is_empty() && !name.contains([':', ' ', '\\'])).then_some(name))
+    }
