94-
95-    let mut indent = Indent::DefaultTwoSpaces;
96-    for line in content.lines() {
97-        let trimmed_start = line.trim_start();
98-        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
99-            let leading = &line[..line.len() - trimmed_start.len()];
100-            if leading.contains('\t') {
101-                indent = Indent::Tabs;
102-            } else {
103-                indent = Indent::Spaces(leading.len() as u8);
104-            }
105-            break;
106-        }
107-    }
