574-pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
575-    match spec {
576:        DepSpec::WorkspaceProtocol(workspace) => {
577-            if workspace.coverage(target).ok()? != callisto_model::Coverage::DoesNotCover {
578-                return None;
579-            }
580-            let range = workspace.range()?;
581-            let rewritten = if Version::parse(range, VersionGrammar::SemVer).is_ok() {
582-                target.render().to_string()
583-            } else {
584-                let req = VersionReq::parse(range, Ecosystem::Npm).ok()?;
585-                round_trip(&DepSpec::Range(req, range.to_string()), target)?.render()
586-            };
587-            let updated = workspace.with_range(&rewritten);
588-            if updated.coverage(target).ok()? != callisto_model::Coverage::Covers {
589-                return None;
590-            }
591:            Some(DepSpec::WorkspaceProtocol(updated))
592-        }
593-        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
594-        DepSpec::Range(_, original) => {
595-            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
596-            if rest.contains(' ') || rest.contains('-') || rest.contains('|') || rest.contains(['x', 'X', '*']) {
597-                return None;
598-            }
599-            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
600-            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
601-            Some(DepSpec::Range(req, rendered))
602-        }
603-        _ => None,
604-    }
605-}
