607-fn render_at_precision(target: &Version, original_clause: &str) -> String {
608-    if target.is_prerelease() {
609-        return target.render().to_string();
610-    }
611-    let parts: Vec<&str> = original_clause.split('.').collect();
612-    let maj = target.major().unwrap_or(0);
613-    let min = target.minor().unwrap_or(0);
614-    let pat = target.patch().unwrap_or(0);
615-
616-    match parts.len() {
617-        1 => format!("{maj}"),
618-        2 => format!("{maj}.{min}"),
619-        _ => format!("{maj}.{min}.{pat}"),
620-    }
621-}
