105-pub(crate) fn caret_covers(cur: &Version, new: &Version) -> Result<bool, GrammarMismatch> {
106-    let cmp = Version::compare(new, cur)?;
107-    if cmp.is_lt() {
108-        return Ok(false);
109-    }
110-    // Pre-release versions are never covered by a caret range: ^1.2.3 must not
111-    // satisfy 1.9.0-alpha.1 even though 1.9.0-alpha.1 > 1.2.3 and they share
112-    // the same major. Caret ranges cover stable releases within the allowed
113-    // major/minor bounds only; a pre-release of an in-range stable version is
114-    // not itself a stable release and must not be treated as covered.
115-    if new.is_prerelease() {
116-        return Ok(false);
117-    }
118-    let cur_maj = cur.major().unwrap_or(0);
119-    let cur_min = cur.minor().unwrap_or(0);
120-    let new_maj = new.major().unwrap_or(0);
121-    let new_min = new.minor().unwrap_or(0);
122-
123-    if cur_maj > 0 {
124-        Ok(new_maj == cur_maj)
125-    } else if cur_min > 0 {
126-        Ok(new_maj == 0 && new_min == cur_min)
127-    } else {
128-        Ok(new == cur)
129-    }
130-}
